def pass_at_k(n, c, k):
    return round(1 - comb(n - c, k) / comb(n, k), 3)

def pass_hat_k(n, c, k):
    return round(comb(c, k) / comb(n, k), 3)

issues = []
base_rate = sum(base["passed"]) / len(base["passed"])
cand_rate = sum(candidate["passed"]) / len(candidate["passed"])
if cand_rate < base_rate - tolerance:
    issues.append(f"success {base_rate:.2f} -> {cand_rate:.2f}")
broke = [t for t, b, c in zip(base["tasks"], base["passed"], candidate["passed"]) if b and not c]
if broke:
    issues.append(f"newly failing: {', '.join(broke)}")
if statistics.mean(candidate["cost"]) > statistics.mean(base["cost"]) * 1.2:
    issues.append("cost up more than 20%")
if p95(candidate["latency"]) > p95(base["latency"]) * 1.2:
    issues.append("p95 latency up more than 20%")
return issues
